// Steps are processed in order because a claim depletes the cap its policy
// has left for later claims, and because each quote's premium depends on how
// many contracts the customer has already been written.
export const run = (scenario: Scenario): ScenarioResult => {
  const ledger: CapLedger = new Map();
  let contractsWritten = 0;

  const results = scenario.steps.map((step) => {
    if (step.op === "claim") return settleClaim(step, scenario.steps, ledger);
    return quote(step, scenario.customer, contractsWritten++);
  });

  return { results };
};

